/*
 * arch/m68k/sau2/hw.h - SAU2 (DN3xx) hardware addresses
 *
 * Generated by: Claude Opus 5.5
 *
 * Device register and device memory addresses are SAU-specific: only the
 * SAU2 is built today, and other SAUs will bring their own header next to
 * this one.  PROM entry points and PROM-known cells, which every m68k Apollo
 * shares, belong in arch/m68k/arch.h instead.  Module data is never
 * addressed absolutely (docs/design-per-process-data.md); only the cells
 * here are, because the hardware decodes them.
 *
 * The hand-written cold-start code (cold/sau2/cold_start.s, dump/sau2/
 * dump.s) cannot include this header: arch/m68k/sau2/iodefs.s restates
 * the page bases it links against (SAU2_PTT_BASE, SAU2_DISPLAY_MEM_BASE,
 * SAU2_DISPLAY_CTRL_REGS, SAU2_RING2_BASE, SAU2_DMAC_BASE, SAU2_DISK_BASE,
 * SAU2_TIMER_BASE, SAU2_SIO_BASE, SAU2_MMU_REGS, SAU2_PFT_BASE) as absolute
 * symbols under the map's names, and tools/check_iodefs.py (`make
 * check-iodefs') fails if the two disagree.  This header is the source of
 * truth.
 *
 * Addresses move here as their modules are converted, not in one sweep.
 * Included by arch/m68k/arch.h.  The host build does not define these
 * names (arch/host/arch.h): a host test that runs code dereferencing one
 * defines the name itself, before the code is included, as the address of
 * a cell or array standing in for the device (e.g. ring/test/test_rcv.c,
 * flp/test/test_flp_do_io.c).  Subsystem headers never test the
 * architecture to choose between the device and a stand-in
 * (tools/check_guards.py).
 */

#ifndef ARCH_M68K_SAU2_HW_H
#define ARCH_M68K_SAU2_HW_H

/*
 * Display controller (SMD, display 1)
 *
 * SAU2_DISPLAY_CTRL_REGS - the controller's 16-bit register window.
 *   SMD_$INIT 0x00E34D8A "move.l #0xff9800,(0x114,A0)" plants it in unit 1's
 *   record (ctrl_regs), and SMD_$DISP1_INT 0x00E26F32
 *   "lea (0xff9800).l,A0" / SMD_$BLINK_CURSOR_1 0x00E2723E
 *   "tst.w 0x00ff9800" address it directly.
 *
 * SAU2_DISPLAY_MEM_BASE - the frame buffer.  SMD_$INIT 0x00E34D82
 *   "move.l #0xfc0000,(0x120,A0)" plants it in unit 1's record
 *   (display_base); SMD_$BLINK_CURSOR_1 0x00E27256 pushes it.
 *
 * The record fields they seed are a pointer (ctrl_regs, SMD_HW_REG_PTR) and
 * a 32-bit VA (display_base), so the register window is given as a pointer
 * and the frame buffer as a VA.
 */
#define SAU2_DISPLAY_CTRL_REGS  ((volatile uint16_t *)0x00FF9800u)
#define SAU2_DISPLAY_MEM_BASE   0x00FC0000u

/*
 * DMA controller (M68450 DMAC, four channels 0x40 bytes apart)
 *
 * SAU2_DMAC_BASE - channels 0..2 belong to the token ring (0: receive
 *   header, 1: receive data, 2: transmit; the register layout within a
 *   channel is the ring driver's, ring/ring_internal.h), channel 3 to the
 *   floppy (flp/flp_internal.h).  Loaded as "movea.l #0xffa000,An" by
 *   ring_$clear_dma_channel 0x00E757F2, ring_$setup_tx_dma 0x00E75868 and
 *   ring_$setup_rx_dma 0x00E758CC, and as "move.l #0xffa000,D4" by FLP_DO_IO
 *   0x00E3DE5E.  dma/dma.h's DN300_DMAC_BASE_ADDRESS is this address.
 */
#define SAU2_DMAC_BASE          0x00FFA000u

/*
 * Calendar (OKI MSM5832 real-time clock interface) and interval timer
 *
 * SAU2_CALENDAR_BASE - map CALENDAR 0xFFA800: control at +0x20, write data
 *   at +0x22, read data at +0x24 (cal/cal.h).  TIME_$READ_CAL loads it from
 *   the constant long at 0x00E2AF66; CAL_$WRITE_CALENDAR spells the three
 *   registers out absolutely.
 * SAU2_TIMER_BASE - map TIMR 0xFFAC00: the timer registers the TIME_ASM
 *   clock readers address as `lea (0xffac00).l,A0' (time/time.h).
 */
#define SAU2_CALENDAR_BASE      0x00FFA800u
#define SAU2_TIMER_BASE         0x00FFAC00u

/*
 * Token ring and disk controller register pages (map IODEFS)
 *
 * SAU2_RING2_BASE - map RING2 0xFF9C00: the ring controller's register
 *   block, the +0x34 cell of RING_DCTE (io/dctes_data.c) that RING_$INT and
 *   RING_$POLL_STICKY_BPHERR reach through the DCTE (ring/ring.h
 *   ring_hw_regs_t).
 * SAU2_DISK_BASE - map DISK / WIN / FLOP 0xFFA800: the Winchester and
 *   floppy controller's register block, the +0x34 cell of FLP_DCTE and
 *   WIN_DCTE.  The calendar (SAU2_CALENDAR_BASE) shares the page at +0x20.
 */
#define SAU2_RING2_BASE         0x00FF9C00u
#define SAU2_DISK_BASE          0x00FFA800u

/*
 * Peripheral floating-point board (PEB) register pages (map IODEFS)
 *
 * SAU2_PEB_CTL - map PEB_CTL / PEB_$M_CTRL_PAGE 0xFF7000: the control
 *   word (its low byte, 0xFF7001, the status byte; byte 0x3FC of the page
 *   is the acknowledge cell PEB_$INT touches).
 * SAU2_PEB_DCMD_PAGE - map PEB_$M_DCMD_PAGE / FPU_CMD 0xFF7400: the
 *   privileged mirror of the register page PEB_$GET_STATUS reads when the
 *   PEB MMU mappings are installed.
 * SAU2_PEB_CS_PAGE - map PEB_$M_CS_PAGE / FPU_CS 0xFF7800: the writable
 *   control store PEB_$LOAD_WCS fills.
 */
#define SAU2_PEB_CTL            ((volatile uint16_t *)0x00FF7000u)
#define SAU2_PEB_DCMD_PAGE      0x00FF7400u
#define SAU2_PEB_CS_PAGE        ((volatile uint16_t *)0x00FF7800u)

/*
 * SAU2_SIO_BASE - map SIO 0xFFB000: the serial controllers' register
 *   blocks, 0x20 bytes per chip, chip n (1-based) at base + (n-1)*0x20.
 *   SIO6509_$INIT (0x00E3353E `movea.l #0xffb000,A3' / `lea
 *   (-0x20,A3,D0w)') and SIO2681_$INIT (sio2681_internal.h
 *   SIO2681_BASE_ADDR) index it that way.
 */
#define SAU2_SIO_BASE           0x00FFB000u

/*
 * The MMU register page (map MMU 0xFFB400) and the MMU's two tables
 *
 * Register names and layouts are Apollo's, from the DN3xx chapter of the
 * Domain Engineering Handbook (002398-04 Rev4, Jan87), pages 7-23..7-27;
 * mmu/mmu.h documents the bits.  Only the hand-written MMU_ASM routines
 * (mmu/sau2/*.s), FIM_$BUS_ERR, IO_$PROBE, PROC1_$DISPATCH, PARITY_$CHK
 * and the FP context code (fp/sau2/fp_context.s, the FPU owner register)
 * touch them; the .s files spell the same addresses as commented `.equ's,
 * since they are not preprocessed.
 *
 * SAU2_MMU_REGS          - the register page itself, 0xFFB400.
 * SAU2_MMU_CSR           - 0xFFB400 word: PID (high byte) / privilege /
 *   PTT-access control and status (`move.w ...,(0xffb400).l' in every
 *   MMU_ASM routine that brackets a table walk).
 * SAU2_MMU_POWER_REG     - 0xFFB402 word: power / status control; its first
 *   byte is the handbook's FPU Owner Register (write-only ASID of the FPU
 *   owner), SAU2_MMU_FPU_OWNER_REG, which MMU_$INSTALL_ASID stores with
 *   `move.b (0x00e218d5).l,(0x00ffb402).l' (0x00E2421C).  MMU_$POWER_OFF
 *   reads the word (0x00E2428C).
 * SAU2_MMU_STATUS_REG    - 0xFFB403 byte: fault / status (bit 4 = normal
 *   mode, MMU_$NORMAL_MODE 0x00E24280).
 * SAU2_MMU_MCR_M68010    - 0xFFB405 byte: memory control on a 68010 CPU.
 * SAU2_MMU_MCR_MASK      - 0xFFB407 byte: its read-back mask.
 * SAU2_MMU_MCR_M68020    - 0xFFB408 byte: memory control on a 68020 CPU
 *   (MMU_$MCR_CHANGE 0x00E242A0).
 * SAU2_MMU_HW_REV        - 0xFFB409 byte: the DN330 MMU hardware revision
 *   MMU_$SET_SYSREV latches (0x00E24276).
 * SAU2_MMU_PARITY_REG    - 0xFFB40A word: MMU parity register, DN3xx only
 *   (FIM_$BUS_ERR).
 * SAU2_MEM_ERR_STATUS_LONG / _WORD - the latched memory error status,
 *   read as a longword at 0xFFB404 and as a word at 0xFFB406 and cleared
 *   through the word by PARITY_$CHK (parity/chk.c).
 *
 * SAU2_PTT_BASE - the page translation table window, 0x700000: one word
 *   per PTT slot (the chain head's ppn), reached as 0x700000 + (va &
 *   VA_TO_PTT_OFFSET_MASK) (`add.l #0x700000,Dn', MMU_$VTOP 0x00E2411C,
 *   mmu_$installi 0x00E240D8; `lea (0x700000).l,A2', mmu_$remove_pmape
 *   0x00E23DE6).  Only addressable while the CSR's PTT-access bit is set.
 * SAU2_PFT_BASE - the page frame table, map PFT 0xFFB800: one longword per
 *   physical page (`lea (0xffb800).l,An' throughout MMU_ASM).
 */
#define SAU2_MMU_REGS            0x00FFB400u
#define SAU2_MMU_CSR             ((volatile uint16_t *)0x00FFB400u)
#define SAU2_MMU_POWER_REG       ((volatile uint16_t *)0x00FFB402u)
#define SAU2_MMU_FPU_OWNER_REG   ((volatile uint8_t *)0x00FFB402u)
#define SAU2_MMU_STATUS_REG      ((volatile uint8_t *)0x00FFB403u)
#define SAU2_MEM_ERR_STATUS_LONG ((volatile uint32_t *)0x00FFB404u)
#define SAU2_MMU_MCR_M68010      ((volatile uint8_t *)0x00FFB405u)
#define SAU2_MEM_ERR_STATUS_WORD ((volatile uint16_t *)0x00FFB406u)
#define SAU2_MMU_MCR_MASK        ((volatile uint8_t *)0x00FFB407u)
#define SAU2_MMU_MCR_M68020      ((volatile uint8_t *)0x00FFB408u)
#define SAU2_MMU_HW_REV          ((volatile uint8_t *)0x00FFB409u)
#define SAU2_MMU_PARITY_REG      ((volatile uint16_t *)0x00FFB40Au)

#define SAU2_PTT_BASE            ((uint16_t *)0x00700000u)
#define SAU2_PFT_BASE            ((uint32_t *)0x00FFB800u)

/*
 * IODEFS buffer pages: fixed virtual pages of the I/O region (map IODEFS
 * 0xFC0000..) that the kernel maps a physical page into with MMU_$INSTALL
 * to look at it.  Virtual addresses, not objects.
 *
 * SAU2_PAR_BUFF - map PAR_BUFF 0xFF9000, PARITY_$CHK's scratch page.
 */
#define SAU2_PAR_BUFF           0x00FF9000u

#endif /* ARCH_M68K_SAU2_HW_H */
